// Generated by npm run build:dh. Edit dh-sync.js and shared/dh-sheet.js.
var DHSheetSync = (function (exports) {
  'use strict';

  // Lớp gọi API Kênh Người Bán Shopee.
  // Mọi request được chạy BÊN TRONG một tab banhang.shopee.vn (qua chrome.scripting),
  // nên trình duyệt tự gửi kèm cookie đăng nhập như khi bạn thao tác trên web.

  const SELLER_ORIGIN = 'https://banhang.shopee.vn';

  let cachedTabId = null;

  function waitTabComplete(tabId, timeout = 45000) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        cleanup();
        reject(new Error('Hết thời gian chờ tải trang Kênh Người Bán'));
      }, timeout);
      function listener(id, info, tab) {
        if (id === tabId && info.status === 'complete') {
          cleanup();
          resolve(tab);
        }
      }
      function cleanup() {
        clearTimeout(timer);
        chrome.tabs.onUpdated.removeListener(listener);
      }
      chrome.tabs.onUpdated.addListener(listener);
      chrome.tabs.get(tabId).then((t) => {
        if (t.status === 'complete') {
          cleanup();
          resolve(t);
        }
      }).catch((e) => {
        cleanup();
        reject(e);
      });
    });
  }

  // Tìm (hoặc mở ngầm) một tab Kênh Người Bán để chạy request.
  async function getSellerTab() {
    if (cachedTabId !== null) {
      try {
        const t = await chrome.tabs.get(cachedTabId);
        if (t.url && t.url.startsWith(SELLER_ORIGIN)) {
          if (t.status !== 'complete') await waitTabComplete(t.id);
          return t.id;
        }
      } catch (e) { /* tab đã đóng */ }
      cachedTabId = null;
    }

    const tabs = await chrome.tabs.query({ url: SELLER_ORIGIN + '/*' });
    let tab = tabs.find((t) => t.status === 'complete') || tabs[0];
    if (!tab) {
      throw new Error('Chưa mở tab Kênh Người Bán Shopee. Vui lòng mở banhang.shopee.vn để tiếp tục.');
    }
    tab = await waitTabComplete(tab.id);
    if (!tab.url || !tab.url.startsWith(SELLER_ORIGIN)) {
      throw new Error('Bạn chưa đăng nhập Kênh Người Bán Shopee. Hãy mở banhang.shopee.vn và đăng nhập.');
    }
    cachedTabId = tab.id;
    return tab.id;
  }

  // Hàm này được inject và chạy trong tab Shopee.
  function pageFetch(url, method, body) {
    return fetch(url, {
      method,
      credentials: 'include',
      signal: AbortSignal.timeout(25000),
      headers: {
        accept: 'application/json, text/plain, */*',
        'content-type': 'application/json'
      },
      body: body == null ? undefined : JSON.stringify(body)
    })
      .then(async (r) => ({ status: r.status, text: await r.text() }))
      .catch((e) => ({ status: 0, text: '', error: String(e) }));
  }

  async function getSpcCds() {
    const c = await chrome.cookies.get({ url: SELLER_ORIGIN, name: 'SPC_CDS' });
    return (c && c.value) || '';
  }

  async function request(method, path, { params = {}, body = null } = {}) {
    const tabId = await getSellerTab();
    const spc = await getSpcCds();
    const qs = new URLSearchParams({ SPC_CDS: spc, SPC_CDS_VER: '2' });
    for (const [k, v] of Object.entries(params)) {
      if (v !== undefined && v !== null && v !== '') qs.set(k, String(v));
    }
    const url = `${SELLER_ORIGIN}${path}?${qs.toString()}`;

    const [injection] = await chrome.scripting.executeScript({
      target: { tabId },
      func: pageFetch,
      args: [url, method, body]
    });
    const result = injection && injection.result;
    if (!result) throw new Error('Không chạy được request trong tab Shopee');
    if (result.error) throw new Error('Lỗi mạng: ' + result.error);
    if (result.status === 401 || result.status === 403) {
      throw new Error(`Shopee từ chối (HTTP ${result.status}). Hãy đăng nhập lại Kênh Người Bán.`);
    }

    let json;
    try {
      json = JSON.parse(result.text);
    } catch (e) {
      throw new Error(`Phản hồi không phải JSON (HTTP ${result.status})`);
    }
    const code = json.code ?? json.error ?? 0;
    if (code) {
      const err = new Error(json.message || json.msg || json.err_msg || `Shopee trả lỗi code ${code}`);
      err.code = code;
      err.response = json;
      throw err;
    }
    return json.data;
  }

  async function getShopInfo() {
    const d = await request('GET', '/api/selleraccount/shop_info/');
    return { name: (d && (d.name || d.shop_name)) || '', shopId: d && (d.shop_id || d.shopid) };
  }

  // ---------- Đơn hàng ----------

  const orders = {
    // 1 trang mã đơn của 1 tab trạng thái. sentinel: lấy từ lần gọi trước.
    async listIndex({ tab, page = 1, pageSize = 40, sentinel = '' }) {
      const body = {
        order_list_tab: Number(tab),
        entity_type: 1,
        pagination: {
          from_page_number: page > 1 ? page - 1 : 1,
          page_number: page,
          page_size: pageSize,
          page_sentinel: sentinel || ''
        },
        filter: { fulfillment_type: 0, is_drop_off: 0, fulfillment_source: 0, action_filter: 0 }
      };
      const d = await request('POST', '/api/v3/order/search_order_list_index', { body });
      const pg = (d && d.pagination) || {};
      return {
        index: (d && d.index_list) || [],
        total: Number(pg.total || 0),
        // Kênh Người Bán dùng previous_page_sentinel cho trang kế tiếp
        sentinel: pg.previous_page_sentinel || pg.next_page_sentinel || ''
      };
    },

    // Chi tiết các đơn (tối đa 5 mã đơn / lần).
    async cards({ tab, index }) {
      const d = await request('POST', '/api/v3/order/get_order_list_card_list', {
        body: { order_list_tab: Number(tab), need_count_down_desc: false, order_param_list: index }
      });
      return ((d && d.card_list) || []).map((c) => c.order_card || c);
    },

    // Chi tiết đầy đủ 1 đơn (trang "Xem chi tiết" của Kênh Người Bán).
    async getOne(orderId) {
      return request('GET', '/api/v3/order/get_one_order', { params: { order_id: orderId } });
    },

    // Thông tin thanh toán / doanh thu của 1 đơn (phần "Thông tin thanh toán" trong trang chi tiết đơn).
    // Shopee chỉ trả bảng doanh thu khi gửi đúng các "components" cần lấy; chưa biết chắc giá trị,
    // nên thử lần lượt các dạng và nhớ dạng nào dùng được cho các đơn sau.
    async income(orderId) {
      const path = '/api/v4/accounting/pc/seller_income/income_detail/get_order_income_components';
      const id = Number(orderId);
      const variants = [
        { order_id: id, components: [2, 3] },
        { order_id: id, components: [1, 2, 3] },
        { order_id: id, components: [1, 2, 3, 4, 5] },
        { order_id: id },
        { order_id: String(orderId), components: [2, 3] }
      ];
      const order = incomeVariant === null ? variants.map((_, i) => i) : [incomeVariant, ...variants.map((_, i) => i).filter((i) => i !== incomeVariant)];
      let last = null;
      let lastErr = null;
      for (const i of order) {
        try {
          const d = await request('POST', path, { body: variants[i] });
          last = d;
          const rows = d && d.seller_income_breakdown && d.seller_income_breakdown.breakdown;
          if (Array.isArray(rows) && rows.length) {
            incomeVariant = i;
            return d;
          }
        } catch (e) {
          lastErr = e;
        }
      }
      if (lastErr && !last) throw lastErr;
      const err = new Error('Shopee không trả bảng doanh thu cho đơn này');
      err.response = last;
      throw err;
    }
  };

  let incomeVariant = null; // dạng request doanh thu đã dùng được

  // Đọc dữ liệu đơn hàng từ "order card" (và chi tiết đơn nếu đã tải) của Kênh Người Bán.
  // Cấu trúc có thể thay đổi, nên các trường được tìm theo tên ở mọi cấp (deep search),
  // và luôn giữ nguyên dữ liệu gốc (raw / detail) để xem / xuất đầy đủ.

  const num = (v) => {
    const n = parseFloat(v);
    return Number.isFinite(n) ? n : 0;
  };

  const isText = (v) => typeof v === 'string' && v.trim() !== '';
  const notEmpty = (v) => v !== undefined && v !== null && v !== '';

  // Tìm giá trị đầu tiên có key nằm trong `keys` (duyệt theo chiều rộng, ưu tiên cấp nông).
  function findDeep(obj, keys, test = notEmpty) {
    const queue = [obj];
    const seen = new Set();
    while (queue.length) {
      const cur = queue.shift();
      if (!cur || typeof cur !== 'object' || seen.has(cur)) continue;
      seen.add(cur);
      for (const k of keys) {
        if (Object.prototype.hasOwnProperty.call(cur, k) && test(cur[k])) return cur[k];
      }
      for (const v of Object.values(cur)) if (v && typeof v === 'object') queue.push(v);
    }
    return undefined;
  }

  const ITEM_ID_KEYS = ['item_id', 'itemid', 'product_id'];
  const hasItemId = (o) => ITEM_ID_KEYS.some((k) => o[k]);
  const looksLikeLine = (o) => ['model_id', 'modelid', 'amount', 'quantity', 'item_price', 'order_price', 'model_name', 'item_sku', 'model_sku']
    .some((k) => o[k] !== undefined);

  // Tất cả "dòng sản phẩm" trong đơn: { node, ctx } — ctx là các object cha gần nhất
  // (tên / phân loại / ảnh thường nằm ở object anh em, không cùng chỗ với item_id).
  function findItems(obj) {
    const out = [];
    const seen = new Set();
    (function walk(o, parents) {
      if (!o || typeof o !== 'object' || seen.has(o)) return;
      seen.add(o);
      if (!Array.isArray(o) && hasItemId(o) && looksLikeLine(o)) {
        out.push({ node: o, ctx: parents.filter((p) => !Array.isArray(p)).slice(-2).reverse() });
        return;
      }
      for (const v of Object.values(o)) walk(v, [...parents, o]);
    })(obj, []);
    const key = (x) => `${x.node.item_id ?? x.node.itemid ?? x.node.product_id}:${x.node.model_id ?? x.node.modelid ?? ''}`;
    const map = new Map();
    for (const x of out) if (!map.has(key(x))) map.set(key(x), x);
    return [...map.values()];
  }

  const isVariationText = (v) => isText(v) && /^\s*(Variation|Phân loại)\s*:/i.test(v);

  // "Variation: Seka 4L [51118880508 S219-BK-00-GDD-00-001-Nồi nấu chậm...]"
  //  -> { model: "Seka 4L", sku: "S219-BK-00-GDD-00-001-Nồi nấu chậm..." }
  function parseVariation(text) {
    const s = String(text || '').replace(/^\s*(Variation|Phân loại)\s*:\s*/i, '').trim();
    const m = s.match(/^(.*?)\s*\[(.*)\]\s*$/);
    if (!m) return { model: s, sku: '' };
    // Trong ngoặc có thể có chữ / ID phía trước SKU: "nồi cơm điện Z067-WH-00-GDD", "51118880508 S219-BK-..."
    // -> SKU bắt đầu từ mã đầu tiên dạng "ABC123-..." (có số và dấu gạch ngang).
    const inside = m[2].trim();
    const code = inside.match(/(?:^|\s)([A-Za-z]*\d[A-Za-z0-9]*-\S.*)$/);
    let sku = code ? code[1].trim() : inside.replace(/^\d{6,}\s+/, '').trim();
    if (/^\d+$/.test(sku)) sku = ''; // chỉ là ID phân loại, không phải SKU
    return { model: m[1].trim(), sku };
  }

  // Tiền: một số API trả giá nhân 100.000
  function money(v) {
    const n = num(v);
    return n >= 1e9 && n % 1000 === 0 ? n / 100000 : n;
  }

  function timeOf(v) {
    const n = num(v);
    if (!n) return 0;
    return n > 1e12 ? Math.floor(n / 1000) : n; // ms -> s
  }

  const IMG = (h) => (!h ? '' : String(h).startsWith('http') ? h : `https://cf.shopee.vn/file/${h}_tn`);

  // "Seka 4L [51118880508 S219-BK-00-...]" -> tên phân loại "Seka 4L"
  function cleanModel(text) {
    return String(text || '').replace(/^Variation:\s*/i, '').replace(/\s*\[[^\]]*\]\s*$/, '').trim();
  }

  function parseItem({ node: it, ctx }) {
    // Tìm trong chính dòng sản phẩm trước, rồi tới các object cha gần nhất.
    const scopes = [it, ...ctx];
    const find = (keys, test) => {
      for (const s of scopes) {
        const v = findDeep(s, keys, test);
        if (v !== undefined) return v;
      }
      return undefined;
    };
    const variationText = find(['description', 'model_description', 'variation_description', 'model_name', 'variation_name', 'variation'], isVariationText) || '';
    const variation = parseVariation(variationText);
    const modelRaw = find(['model_name', 'variation_name', 'variation', 'model_desc', 'tier_variation_name'], (v) => isText(v) && !isVariationText(v)) || '';
    // `name` ở dòng model có thể chỉ là tên phân loại. Tìm tên sản phẩm
    // tường minh ở mọi scope trước, rồi mới dùng title/name của nhóm sản phẩm.
    const nameOk = (v) => isText(v) && !isVariationText(v);
    const productName = scopes.flatMap((s) => [s.product?.name, s.item_info?.item_name, s.item_info?.name, s.item_name, s.product_name]).find(nameOk)
      || scopes.map((s) => s.title).find(nameOk)
      || [...ctx, it].map((s) => s.name).find(nameOk)
      || findDeep(it, ['item_name', 'product_name'], nameOk)
      || findDeep(it, ['name', 'title'], nameOk)
      || '';
    return {
      itemId: Number(it.item_id ?? it.itemid ?? it.product_id),
      modelId: Number(it.model_id ?? it.modelid ?? 0),
      name: productName,
      model: cleanModel(it.item_model?.name || modelRaw) || variation.model,
      itemSku: it.product?.sku || find(['item_sku', 'parent_sku', 'product_sku'], isText) || '',
      modelSku: it.item_model?.sku || find(['model_sku', 'variation_sku', 'sku'], isText) || variation.sku,
      variationText,
      qty: num(find(['amount', 'quantity', 'item_count', 'qty']) ?? 1) || 1,
      price: money(find(['order_price', 'item_price', 'discounted_price', 'price'])),
      originalPrice: money(find(['original_price', 'price_before_discount'])),
      image: IMG(find(['image', 'item_image', 'cover_image', 'product_image'], isText))
    };
  }

  // "Lấy hàng vào ngày {timestamp}" -> "Lấy hàng vào ngày 15/10/2026".
  // Giá trị thay vào {tên} lấy từ các trường cùng tên trong status_description (hoặc mảng tham số).
  function describeStatus(desc, fallback = null) {
    if (!desc) return '';
    if (typeof desc === 'string') return desc;
    const tpl = desc.description_value || desc.description || desc.text || '';
    if (!isText(tpl)) return '';
    const fmtTs = (v) => {
      const n = num(v);
      if (n < 1e9) return String(v);
      const d = new Date((n > 1e12 ? n : n * 1000));
      return d.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
    };
    // Tập tham số: mọi cặp key/value trong desc (kể cả trong mảng tham số dạng {key, value})
    const params = {};
    (function walk(o) {
      if (!o || typeof o !== 'object') return;
      if (!Array.isArray(o) && o.key !== undefined && o.value !== undefined) params[o.key] = o.value;
      for (const [k, v] of Object.entries(o)) {
        if (v && typeof v === 'object') walk(v);
        else if (k !== 'description_value') params[k] = params[k] ?? v;
      }
    })(desc);
    // Không có mốc thời gian trong status_description thì tìm trong status_info (fallback)
    const anyTs = Object.values(params).find((v) => num(v) >= 1e9)
      ?? (fallback ? findDeep(fallback, ['timestamp', 'pickup_time', 'ship_by_date', 'deadline', 'time', 'update_time'], (v) => num(v) >= 1e9) : undefined);
    return tpl.replace(/\{(\w+)\}/g, (_, name) => {
      const v = params[name] ?? (/time|date|timestamp/i.test(name) ? anyTs : undefined);
      if (v === undefined) return `{${name}}`;
      return /time|date|timestamp/i.test(name) || num(v) >= 1e9 ? fmtTs(v) : String(v);
    });
  }

  // Mọi object nằm dưới key `key` ở mọi cấp
  function allObjectsByKey(obj, key) {
    const out = [];
    const seen = new Set();
    (function walk(o) {
      if (!o || typeof o !== 'object' || seen.has(o)) return;
      seen.add(o);
      if (!Array.isArray(o) && o[key] && typeof o[key] === 'object') out.push(o[key]);
      for (const v of Object.values(o)) walk(v);
    })(obj);
    return out;
  }

  // Mã đơn Shopee bắt đầu bằng YYMMDD: "261015N7H1YQ42" -> 15/10/2026
  function dateFromOrderSn(sn) {
    const m = String(sn || '').match(/^(\d{2})(\d{2})(\d{2})/);
    if (!m) return null;
    const [y, mo, d] = [2000 + Number(m[1]), Number(m[2]), Number(m[3])];
    if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
    return { y, m: mo, d, text: `${String(d).padStart(2, '0')}/${String(mo).padStart(2, '0')}/${y}`, time: new Date(y, mo - 1, d).getTime() / 1000 };
  }

  const TRACKING_KEYS = ['tracking_number', 'tracking_no', 'third_party_tn', 'shipping_traceno', 'consignment_no', 'logistics_tracking_number', 'tn'];

  /**
   * card: order card từ danh sách đơn. detail: dữ liệu chi tiết đơn (nếu đã tải), được ưu tiên khi có.
   */
  function parseOrder(card, detail = null) {
    const src = detail ? { detail, card } : card;
    const ext = card.order_ext_info || {};
    const header = card.card_header || {};
    const buyer = header.buyer_info || findDeep(src, ['buyer_info']) || {};
    const pick = (keys, test) => findDeep(src, keys, test);

    let items = findItems(src).map(parseItem);
    // Không tìm thấy dòng sản phẩm có item_id: dựng 1 dòng từ chữ "Variation: ..." nếu có
    if (!items.length) {
      const vt = findDeep(src, ['description', 'model_name', 'variation'], isVariationText);
      if (vt) {
        const v = parseVariation(vt);
        items = [{ itemId: 0, modelId: 0, name: findDeep(src, ['item_name', 'product_name'], isText) || '', model: v.model,
          itemSku: '', modelSku: v.sku, variationText: vt, qty: 1, price: 0, originalPrice: 0, image: '' }];
      }
    }

    // Trạng thái: chỉ nhận chữ mô tả, không lấy số mã trạng thái hay dòng "Variation: ..."
    const statusOk = (v) => isText(v) && !isVariationText(v) && !/^\d+$/.test(v.trim());

    // Kiện hàng: card.package_level_order_card.package_list[]
    //   .fulfilment_info.tracking_number_list[]  -> mã vận đơn
    //   .status_info.status                      -> trạng thái
    //   .status_info.status_description.description_value (có {timestamp}) -> mô tả trạng thái
    const packages = (card.package_level_order_card && card.package_level_order_card.package_list) || [];
    // Mã vận đơn có thể nằm ở từng kiện hàng hoặc ngay card.fulfilment_info
    const pkgTracking = [...new Set([
      ...packages.flatMap((p) => (p.fulfilment_info && p.fulfilment_info.tracking_number_list) || []),
      ...((card.fulfilment_info && card.fulfilment_info.tracking_number_list) || [])
    ].filter(isText))];
    // Trạng thái: ưu tiên status_info của kiện hàng, rồi status_info cấp đơn, rồi mọi status_info khác
    const statusInfos = [...packages.map((p) => p.status_info), card.status_info,
      card.package_level_order_card && card.package_level_order_card.status_info, ...allObjectsByKey(card, 'status_info')].filter(Boolean);
    const pkgStatus = statusInfos.find((s) => statusOk(s.status) || statusOk(s.status_text) || statusOk(s.status_name));
    if (pkgStatus && !statusOk(pkgStatus.status)) pkgStatus.status = pkgStatus.status_text || pkgStatus.status_name;
    const pkgChannel = [...packages.map((p) => p.fulfilment_info || {}), card.fulfilment_info || {}].find((f) => f && (f.fulfilment_channel_name || f.channel_name));

    // Kiện hàng để in phiếu giao: mã kiện (OFG...) + kênh vận chuyển (channel_id, vd 50021 = SPX)
    const CHANNEL_KEYS = ['channel_id', 'fulfilment_channel_id', 'fulfillment_channel_id', 'logistics_channel_id', 'checkout_channel_id'];
    const isId = (v) => num(v) > 0;
    const cardChannel = findDeep(card, CHANNEL_KEYS, isId);
    let shipPackages = packages
      .map((p) => ({ packageNumber: p.package_number || findDeep(p, ['package_number', 'package_sn'], isText) || '', channelId: num(findDeep(p, CHANNEL_KEYS, isId) || cardChannel) }))
      .filter((p) => p.packageNumber);
    if (!shipPackages.length) {
      const pn = findDeep(card, ['package_number', 'package_sn'], isText);
      if (pn) shipPackages = [{ packageNumber: pn, channelId: num(cardChannel) }];
    }
    const orderSn = String(header.order_sn ?? pick(['order_sn']) ?? '');
    const snDate = dateFromOrderSn(orderSn);

    return {
      orderId: String(ext.order_id ?? pick(['order_id']) ?? ''),
      orderSn,
      buyer: buyer.username || buyer.buyer_username || pick(['buyer_username', 'username'], isText) || '',
      buyerId: String(ext.buyer_user_id ?? buyer.user_id ?? pick(['buyer_user_id', 'buyer_userid']) ?? ''),
      statusCode: (statusInfos.map((x) => x.status).find((v) => /^\d+$/.test(String(v ?? ''))) ?? ''),
      status: (pkgStatus && pkgStatus.status)
        || pick(['status_text', 'order_status_text', 'status_desc', 'status_title', 'list_view_status_text', 'status_name'], statusOk) || '',
      statusNote: (pkgStatus && describeStatus(pkgStatus.status_description, pkgStatus))
        || pick(['sub_status_text', 'status_sub_text', 'status_sub_title'], statusOk) || '',
      // Ngày đặt lấy từ 6 ký tự đầu mã đơn (YYMMDD); nếu không được mới dùng thời gian Shopee trả về
      orderDate: snDate ? snDate.text : '',
      createTime: (snDate && snDate.time) || timeOf(pick(['create_time', 'order_create_time', 'ctime'])),
      total: money(pick(['total_price', 'order_total', 'buyer_total_amount', 'total_amount', 'order_price_total'])),
      payment: pick(['payment_method_name', 'payment_method', 'payment_channel_name', 'payment_method_text'], isText) || '',
      shippingType: pick(['shipping_method_name', 'fulfilment_channel_type', 'channel_type_name'], isText) || '',
      shipping: (pkgChannel && (pkgChannel.fulfilment_channel_name || pkgChannel.channel_name)) || pick(['fulfilment_channel_name', 'fulfillment_channel_name', 'channel_name', 'logistics_channel_name', 'shipping_channel_name', 'carrier_name'], isText) || '',
      // Mã vận đơn: ưu tiên tracking_number_list của kiện hàng (nhiều kiện thì nối bằng ", ")
      tracking: pkgTracking.join(', ') || (detail ? findDeep(detail, TRACKING_KEYS, isText) : '') || '',
      shipBy: timeOf(pick(['ship_by_date', 'days_to_ship_deadline', 'ship_by_time', 'pickup_time', 'pickup_date'])),
      note: pick(['remark', 'buyer_note', 'message_to_seller', 'note'], isText) || '',
      address: detail ? (pick(['full_address', 'shipping_address', 'address'], isText) || '') : '',
      shippingFee: detail ? money(pick(['actual_shipping_fee', 'shipping_fee', 'estimated_shipping_fee'])) : 0,
      escrow: detail ? money(pick(['escrow_amount', 'seller_income', 'order_income'])) : 0,
      items,
      packages: shipPackages,
      raw: card,
      detail
    };
  }

  // Tiền trong API doanh thu luôn nhân 100.000
  const incomeMoney = (v) => Math.round(num(v) / 1000) / 100;

  /**
   * -> { byField: { FIELD_NAME: amount }, rows: [{ level, field, name, amount, caption, details: [{ name, amount }] }] }
   */
  function parseIncome(data) {
    const breakdown = (data && data.seller_income_breakdown && data.seller_income_breakdown.breakdown) || [];
    const byField = {};
    const rows = [];
    const feeDetails = (ext) => {
      if (!ext) return [];
      const lists = [ext.service_fee_infos, ext.commission_fee_infos, ext.seller_txn_fee_info ? [ext.seller_txn_fee_info] : null]
        .filter(Array.isArray).flat();
      return lists
        .filter((f) => f && (f.name || num(f.amount) || num(f.fee_rate)))
        .map((f) => ({ name: f.name || '', amount: incomeMoney(f.amount), rate: f.fee_rate ? f.fee_rate / 1000 : 0 }));
    };
    const add = (b, level) => {
      const amount = b.hide_amount ? null : incomeMoney(b.amount);
      if (b.field_name) byField[b.field_name] = amount;
      rows.push({ level, field: b.field_name || '', name: b.display_name || b.field_name || '', amount, caption: b.caption || '', details: feeDetails(b.ext_info) });
      for (const s of b.sub_breakdown || []) add(s, level + 1);
    };
    breakdown.forEach((b) => add(b, 0));
    return { byField, rows, escrow: byField.ESCROW_AMOUNT ?? null };
  }

  // Schema chung cho extension và web. Giữ 27 cột DH cũ, chỉ nối thêm cột.
  const LEGACY_HEADERS = ['gian','ngay','ngay_gio','mdh','mvd','tong_tien','ma_giam_gia','phi_vc','phu_phi','thue','doanh_thu','phi_khac','tien_sp','loi_nhuan','tinh_trang','trang_thai','sku','id_sp','slg','don_gia','thanh_tien','ten_khach','ng_nhan','dia_chi','link_don','mvd_huy','mdh_huy'];
  const RAW_HEADERS = Array.from({length:12},(_,i)=>`du_lieu_goc_${i+1}`);
  const HEADERS = [...LEGACY_HEADERS,'shop_id','order_id','item_id','model_id','ten_sp','phan_loai','anh','sku_san_pham','nguoi_mua_id','sdt','don_vi_vc','hinh_thuc_vc','thanh_toan','han_giao','ghi_chu','mo_ta_trang_thai','ma_trang_thai','ly_do_huy','ly_do_tra_hoan','ngay_hoan_thanh','ngay_huy','phi_co_dinh','phi_dich_vu','phi_giao_dich','thue_gtgt','thue_tncn','vc_nguoi_mua','vc_tro_gia','chi_tiet_phi','chi_tiet_dong_bo','dong_bo_luc',...RAW_HEADERS];
  const norm = s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().trim();
  function statusOf(text) {
    const t=norm(text);
    if(/tra hang.*hoan tien|return.*refund/.test(t))return 'Trả hàng / Hoàn tiền';
    if(/hoan tien|refund/.test(t))return 'Hoàn tiền';
    if(/hoan hang|chuyen hoan|tra ve nguoi ban|return to sender/.test(t))return 'Hoàn hàng';
    if(/tra hang|return/.test(t))return 'Trả hàng';
    if(/huy|cancel/.test(t))return 'Đã hủy';
    if(/hoan thanh|completed/.test(t))return 'Hoàn thành';
    if(/dang giao|dang van chuyen|da giao cho|da ban giao|shipping|shipped/.test(t))return 'Đang giao';
    if(/da giao|giao thanh cong|giao hang thanh cong|da nhan|delivered/.test(t))return 'Đã giao';
    if(/cho lay|chuan bi|cho giao|ready.to.ship|to.ship/.test(t))return 'Chờ lấy hàng';
    if(/thanh toan|unpaid/.test(t))return 'Chờ thanh toán';
    if(/xac nhan|pending/.test(t))return 'Chờ xác nhận';
    return 'Khác';
  }
  const terminal = s=>['Hoàn thành','Đã hủy','Hoàn tiền','Hoàn hàng'].includes(statusOf(s));
  function timestamp(value) {const n=Number(value);return n>0?new Date(n<1e12?n*1000:n).toISOString():'';}
  function recordsForOrder(o,shop,code,findDeep,at=Date.now()) {
    if(!o.orderSn || !shop.shopId || !code)throw new Error('Thiếu mã đơn hoặc mã gian/ID shop');
    const d=o.detail||{}, text=keys=>findDeep(d,keys,v=>typeof v==='string'&&v.trim())||'';
    const date=keys=>timestamp(findDeep(d,keys,v=>Number(v)>0));
    const f=o.income?.byField||{}, hasIncome=!!o.income, detailOK=!!o.detail;
    const base={gian:code,mdh:o.orderSn,shop_id:String(shop.shopId),order_id:o.orderId,ngay:o.orderDate,
      ngay_gio:date(['create_time','order_create_time','ctime'])||timestamp(o.createTime),
      mvd:o.tracking,tong_tien:o.total,trang_thai:statusOf(o.status),mo_ta_trang_thai:[o.status,o.statusNote].filter(Boolean).join(' · '),ma_trang_thai:o.statusCode,
      ten_khach:o.buyer,nguoi_mua_id:o.buyerId,don_vi_vc:o.shipping,hinh_thuc_vc:o.shippingType,thanh_toan:o.payment,han_giao:timestamp(o.shipBy),ghi_chu:o.note,
      link_don:`https://banhang.shopee.vn/portal/sale/order/${encodeURIComponent(o.orderId)}`,
      chi_tiet_dong_bo:[detailOK?'Chi tiết: đã tải':`Chi tiết: ${o.detailError||'chưa tải'}`,hasIncome?'Doanh thu: đã tải':`Doanh thu: ${o.incomeError||'chưa có'}`].join(' · '),dong_bo_luc:new Date(at).toISOString()};
    if(detailOK)Object.assign(base,{ng_nhan:text(['recipient_name','name_of_recipient','receiver_name','buyer_address_name']),sdt:text(['recipient_phone','phone_number','buyer_address_phone','phone']),dia_chi:o.address,
      ly_do_huy:text(['cancel_reason','cancellation_reason','cancel_reason_description']),ly_do_tra_hoan:text(['return_reason','refund_reason','return_reason_description']),ngay_hoan_thanh:date(['complete_time','completed_time']),ngay_huy:date(['cancel_time','cancelled_time'])});
    if(hasIncome){
      const mapping={phu_phi:'FEES_AND_CHARGES',thue:'TAX_SUBTOTAL',doanh_thu:'ESCROW_AMOUNT',phi_vc:'ACTUAL_SHIPPING_FEE',phi_co_dinh:'COMMISSION_FEE',phi_dich_vu:'SERVICE_FEE',phi_giao_dich:'TRANSACTION_FEE',thue_gtgt:'VAT_WHT_AMOUNT',thue_tncn:'PIT_WHT_AMOUNT',vc_nguoi_mua:'SHIPPING_FEE_PAID_BY_BUYER',vc_tro_gia:'SHIPPING_REBATE_FROM_SHOPEE'};
      for(const [key,field]of Object.entries(mapping))if(f[field]!=null)base[key]=f[field];
      base.chi_tiet_phi=JSON.stringify(o.income.rows||[]);
    }
    // Chia JSON để không vượt giới hạn 50.000 ký tự/ô. Không cắt mất dữ liệu.
    const raw=JSON.stringify({card:o.raw,detail:o.detail||null,income:o.incomeRaw||null});
    if(raw.length>RAW_HEADERS.length*45000)throw new Error(`Dữ liệu đơn ${o.orderSn} vượt dung lượng lưu JSON`);
    return (o.items.length?o.items:[{}]).map((it,i)=>{
      const r={...base,ten_sp:it.name||'',phan_loai:it.model||'',anh:it.image||'',sku:it.modelSku||'',sku_san_pham:it.itemSku||'',item_id:String(it.itemId||''),model_id:String(it.modelId||''),slg:it.qty??'',don_gia:it.price??'',thanh_tien:it.price!=null&&it.qty!=null?it.price*it.qty:''};
      RAW_HEADERS.forEach((h,n)=>r[h]=i===0?raw.slice(n*45000,(n+1)*45000):'');
      return r;
    });
  }
  function mergePlan(values,incoming) {
    const oldHeaders=(values[0]||[]).map(x=>String(x).trim());
    if(values.length>1&&(!oldHeaders.includes('mdh')||!oldHeaders.includes('gian')))throw new Error('Sheet DH thiếu cột mdh/gian; giữ nguyên dữ liệu, không ghi đè');
    if(new Set(oldHeaders.filter(Boolean)).size!==oldHeaders.filter(Boolean).length)throw new Error('Sheet DH có tiêu đề trùng');
    const headers=[...oldHeaders];for(const h of HEADERS)if(!headers.includes(h))headers.push(h);
    const objects=values.slice(1).map((row,i)=>({row:i+1,data:Object.fromEntries(oldHeaders.map((h,j)=>[h,row[j]??'']))}));
    const updates=[],used=new Set();let next=values.length||1;
    const groupKey=r=>JSON.stringify([norm(r.gian),String(r.mdh)]), groups=new Map();
    for(const r of incoming){const k=groupKey(r);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r);}
    for(const rows of groups.values()){
      const sample=rows[0], candidates=objects.filter(x=>groupKey(x.data)===groupKey(sample)&&(!x.data.shop_id||String(x.data.shop_id)===String(sample.shop_id)));
      for(const r of rows){
        const match=candidates.find(x=>!used.has(x.row)&&r.item_id&&String(x.data.item_id)===r.item_id&&String(x.data.model_id)===r.model_id)
          ||candidates.find(x=>!used.has(x.row)&&r.sku&&x.data.sku===r.sku)
          ||candidates.find(x=>!used.has(x.row));
        const row=match?match.row:next++;used.add(row);
        // Chỉ cập nhật các cột lấy từ Shopee, giữ giá vốn/lợi nhuận/ghi chú thủ công và cột lạ.
        const data={...r};
        if(match){
          for(const h of ['sku','ten_sp','phan_loai','anh','mvd','item_id','model_id','sku_san_pham'])if(data[h]===''&&match.data[h])delete data[h];
          if(match.data.dong_bo_luc&&String(r.chi_tiet_dong_bo).includes('Chi tiết:')&&!String(r.chi_tiet_dong_bo).includes('Chi tiết: đã tải'))RAW_HEADERS.forEach(h=>delete data[h]);
        }
        updates.push({row,data});
      }
      for(const stale of candidates)if(!used.has(stale.row))updates.push({row:stale.row,clear:true});
    }
    return {headers,updates,rowCount:Math.max(next,values.length,1)};
  }

  const ALARM='dh-all-orders-sheet',CFG='dh_sheet_enabled';
  let running=null;
  const cell=v=>({userEnteredValue:typeof v==='number'?{numberValue:v}:{stringValue:String(v??'')}});
  async function writeOrders(records) {
    const spreadsheetId=self.SHARED_GOOGLE_CONFIG.webSpreadsheetId,token=await getGoogleAccessToken();
    const title=await ensureSheetExists('DH',token,spreadsheetId);
    const meta=await fetchSpreadsheetMetadata(token,spreadsheetId),p=meta.sheets.find(s=>s.properties.title===title).properties;
    const rangeTitle=`'${title.replace(/'/g,"''")}'`;
    const [headers=[]]=await fetchSheetValues(`${rangeTitle}!1:1`,token,30000,spreadsheetId);
    const last=headers.reduce((n,h,i)=>RAW_HEADERS.includes(h)?n:Math.max(n,i),0);
    let col='';for(let n=last+1;n;n=Math.floor((n-1)/26))col=String.fromCharCode(65+(n-1)%26)+col;
    const old=await fetchSheetValues(`${rangeTitle}!A:${col}`,token,30000,spreadsheetId);
    if(headers.length)old[0]=headers;
    const plan=mergePlan(old,records),requests=[];
    if(p.gridProperties.columnCount<plan.headers.length)requests.push({appendDimension:{sheetId:p.sheetId,dimension:'COLUMNS',length:plan.headers.length-p.gridProperties.columnCount}});
    if(p.gridProperties.rowCount<plan.rowCount)requests.push({appendDimension:{sheetId:p.sheetId,dimension:'ROWS',length:plan.rowCount-p.gridProperties.rowCount}});
    requests.push({updateCells:{start:{sheetId:p.sheetId,rowIndex:0,columnIndex:0},rows:[{values:plan.headers.map(cell)}],fields:'userEnteredValue'}});
    for(const update of plan.updates){
      if(update.clear){requests.push({updateCells:{range:{sheetId:p.sheetId,startRowIndex:update.row,endRowIndex:update.row+1,startColumnIndex:0,endColumnIndex:plan.headers.length},fields:'userEnteredValue'}});continue;}
      // Một request cho từng đoạn cột liền nhau; cột do người dùng nhập không bị ghi lại.
      let start=-1,values=[];
      const flush=()=>{if(start>=0)requests.push({updateCells:{start:{sheetId:p.sheetId,rowIndex:update.row,columnIndex:start},rows:[{values}],fields:'userEnteredValue'}});start=-1;values=[];};
      plan.headers.forEach((h,i)=>{if(Object.hasOwn(update.data,h)){const v=update.data[h];if(String(v??'').length>49000)throw new Error(`Nội dung cột ${h} quá dài`);if(start<0)start=i;values.push(cell(v));}else flush();});flush();
    }
    requests.push({updateSheetProperties:{properties:{sheetId:p.sheetId,gridProperties:{frozenRowCount:1}},fields:'gridProperties.frozenRowCount'}});
    const {res,data}=await fetchJsonWithTimeout(`https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}:batchUpdate`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({requests})},60000);
    if(!res.ok)throw new Error(data.error?.message||'Không ghi được DH');
  }
  const freshCursor=()=>({page:1,sentinel:'',pending:[],fingerprint:'',seen:0,total:0,complete:false});
  async function takePage(cursor) {
    if(cursor.pending.length||cursor.complete)return;
    const page=await orders.listIndex({tab:100,page:cursor.page,pageSize:40,sentinel:cursor.sentinel});
    if(!Array.isArray(page.index))throw new Error('Danh sách đơn Shopee không hợp lệ');
    const fingerprint=JSON.stringify(page.index);
    if(page.index.length&&cursor.page>1&&fingerprint===cursor.fingerprint)throw new Error('Shopee lặp trang; chưa xác nhận tải đủ đơn');
    if(!page.index.length&&cursor.seen<page.total)throw new Error('Shopee trả trang rỗng trước tổng số đơn; sẽ thử lại');
    cursor.total=page.total;cursor.pending=page.index;cursor.fingerprint=fingerprint;
    cursor.sentinel=page.sentinel;cursor.page++;
    cursor.lastPage=page.index.length<40;
    if(!page.index.length)cursor.complete=true;
  }
  async function run() {
    const cfg=await chrome.storage.local.get([CFG,'tcdd-shop-code','maGian','dhHoanTextValue']);
    if(cfg[CFG]===false)return {ok:true,paused:true};
    const code=String(cfg['tcdd-shop-code']||cfg.maGian||cfg.dhHoanTextValue||'').trim().toUpperCase();
    if(!code)throw new Error('Nhập Mã gian trong Auto In trước khi đồng bộ DH');
    const shop=await getShopInfo();if(!shop.shopId)throw new Error('Không xác định được shop Shopee');
    // Gắn mã gian với shop thật: không trộn lịch sử khi chuyển tài khoản.
    const key=`dh_sync_${shop.shopId}_${code}`,saved=await chrome.storage.local.get(key);
    const state=saved[key]||{history:freshCursor(),active:{},ticks:0};state.ticks++;
    if(state.history.complete&&Date.now()-(state.completedAt||0)>6*3600000)state.history=freshCursor();
    await takePage(state.history);
    const historyBatch=state.history.pending.slice(0,5);
    let indices=[...historyBatch];
    // Cập nhật đơn mới và đơn chưa kết thúc trong khi đang quét lịch sử cũ.
    if(state.ticks%5===1){const recent=await orders.listIndex({tab:100,page:1,pageSize:5});indices.push(...recent.index);}
    const active=Object.values(state.active).filter(a=>!a.nextAt||a.nextAt<=Date.now()).sort((a,b)=>a.at-b.at).slice(0,3);
    indices.push(...active.map(a=>a.index));
    const indexId=x=>String(x?.order_id||x?.order_sn||'');
    indices=[...new Map(indices.map(x=>[indexId(x),x])).values()];
    if(indices.some(x=>!indexId(x)))throw new Error('Chỉ mục Shopee thiếu mã đơn');
    const records=[],updates=[];let warnings=[];
    for(let i=0;i<indices.length;i+=5){
      const chunk=indices.slice(i,i+5),cards=await orders.cards({tab:100,index:chunk});
      const parsed=cards.map(c=>parseOrder(c));
      if(chunk.some(x=>!parsed.some(o=>indexId(x)===String(o.orderId)||indexId(x)===o.orderSn)))throw new Error('Shopee trả thiếu đơn; giữ vị trí để tải lại');
      for(const card of cards){
        let o=parseOrder(card);if(!o.orderId)throw new Error('Đơn thiếu ID chi tiết');
        try {o=parseOrder(card,await orders.getOne(o.orderId));}catch(e){o.detailError=e.message;}
        try {o.incomeRaw=await orders.income(o.orderId);o.income=parseIncome(o.incomeRaw);}catch(e){o.incomeError=e.message;}
        records.push(...recordsForOrder(o,shop,code,findDeep));
        if(o.detailError||o.incomeError)warnings.push(o.orderSn);
        const index=chunk.find(x=>indexId(x)===String(o.orderId)||indexId(x)===o.orderSn);
        updates.push({id:o.orderId,index,status:o.status,retry:!!(o.detailError||o.incomeError)});
      }
    }
    // Kiểm tra lại tài khoản trước khi ghi; không gán đơn shop khác vào mã gian cũ.
    const check=await getShopInfo();if(String(check.shopId)!==String(shop.shopId))throw new Error('Shop đã thay đổi trong lúc tải. Chưa ghi DH, hãy thử lại');
    await writeOrders(records);
    for(const x of updates){if(!terminal(x.status)||x.retry)state.active[x.id]={index:x.index,at:Date.now(),nextAt:Date.now()+(terminal(x.status)?3600000:300000)};else delete state.active[x.id];}
    state.history.pending.splice(0,historyBatch.length);state.history.seen+=historyBatch.length;
    if(!state.history.pending.length&&state.history.lastPage){
      if(state.history.seen<state.history.total)throw new Error('Chưa đủ tổng số đơn Shopee; không đánh dấu hoàn tất');
      state.history.complete=true;state.completedAt=Date.now();
    }
    const info={at:Date.now(),code,shopId:shop.shopId,seen:state.history.seen,total:state.history.total,complete:state.history.complete,warning:warnings.length?`${warnings.length} đơn chưa có đủ chi tiết/doanh thu; sẽ thử lại`:''};
    await chrome.storage.local.set({[key]:state,dh_sheet_meta:info,dh_sheet_error:''});
    return {ok:true,...info};
  }
  function sync(){if(running)return running;running=run().catch(async e=>{await chrome.storage.local.set({dh_sheet_error:e.message});return {ok:false,error:e.message};}).finally(()=>running=null);return running;}
  chrome.alarms.create(ALARM,{periodInMinutes:1});
  chrome.alarms.onAlarm.addListener(a=>{if(a.name===ALARM)sync();});
  chrome.runtime.onMessage.addListener((msg,sender,reply)=>{
    if(msg?.type==='dh-sync-sheet'){sync().then(reply);return true;}
    return false;
  });

  exports.writeOrders = writeOrders;

  return exports;

})({});
